// ScrollUp fallback plugin
(function($) {
    'use strict';
    
    // Ensure jQuery is available
    if (typeof $ === 'undefined') return;
    
    $.scrollUp = function(options) {
        const settings = $.extend({
            scrollName: 'scrollUp',
            scrollDistance: 300,
            scrollFrom: 'top',
            scrollSpeed: 300,
            easingType: 'linear',
            animation: 'fade',
            animationSpeed: 200,
            scrollTrigger: false,
            scrollTarget: false,
            scrollText: 'Scroll to top',
            scrollTitle: false,
            scrollImg: false,
            activeOverlay: false,
            zIndex: 2147483647
        }, options);
        
        // Create scroll button
        const scrollButton = $('<a/>', {
            id: settings.scrollName,
            href: '#top',
            title: settings.scrollText
        }).appendTo('body');
        
        // Position and style
        scrollButton.css({
            display: 'none',
            position: 'fixed',
            'z-index': settings.zIndex
        });
        
        // Show/hide on scroll
        $(window).scroll(function() {
            if ($(this).scrollTop() > settings.scrollDistance) {
                scrollButton.fadeIn(settings.animationSpeed);
            } else {
                scrollButton.fadeOut(settings.animationSpeed);
            }
        });
        
        // Click handler
        scrollButton.click(function(e) {
            e.preventDefault();
            $('html, body').animate({
                scrollTop: 0
            }, settings.scrollSpeed, settings.easingType);
        });
    };
    
})(jQuery);
